            <div class="stat-grid"><article class="stat-card"><span class="stat-label">Hitos</span><strong class="stat-value"><?= count($detail['hitos']) ?></strong></article><article class="stat-card"><span class="stat-label">Hitos pendientes</span><strong class="stat-value"><?= count(array_filter($detail['hitos'],static fn(array $h):bool=>in_array($h['estado'],['pendiente','observado','corregido'],true))) ?></strong></article><article class="stat-card"><span class="stat-label">Sesiones</span><strong class="stat-value"><?= (int) $attendance['sesiones'] ?></strong></article><article class="stat-card"><span class="stat-label">Asistencia registrada</span><strong class="stat-value"><?= $attendance['porcentaje_presencia'] === null ? '—' : e(number_format((float) $attendance['porcentaje_presencia'],2)) . '%' ?></strong></article></div>
