    </section>

    <?php if ($detail): ?>
        <section class="card mg-panel"><h2>Hitos e informes</h2>
            <?php if ($detail['hitos']): ?><div class="table-wrapper"><table><thead><tr><th>Orden / etapa</th><th>Hito</th><th>Fecha</th><th>Avance</th><th>Estado</th><th>Informes/versiones y revisión</th></tr></thead><tbody>
                <?php foreach ($detail['hitos'] as $milestone): ?><tr><td><?= (int) $milestone['orden'] ?> · <?= e(strtoupper($milestone['etapa'])) ?></td><td><?= e($milestone['nombre']) ?><br><small><?= e($milestone['tipo']) ?></small></td><td><?= e($milestone['fecha_limite'] ?? '—') ?><?= (int) $milestone['vencido'] === 1 ? ' · Vencido' : '' ?></td><td><?= $milestone['avance_real_pct'] === null ? '—' : e($milestone['avance_real_pct']) . '%' ?><?= $milestone['avance_esperado_pct'] === null ? '' : ' / esperado ' . e($milestone['avance_esperado_pct']) . '%' ?></td><td><?= e($milestone['estado']) ?></td><td>
                    <?php if ($milestone['versiones']): ?><ul><?php foreach ($milestone['versiones'] as $version): ?><li>V<?= (int) $version['numero_version'] ?> · <?= e($version['estado']) ?> · <a href="<?= e(app_url('modalidades-grado/descargar-informe.php?id=' . (int) $version['id_version'])) ?>">PDF: <?= e($version['nombre_archivo']) ?></a> · <?= e($version['subido_por']) ?> (<?= e($version['subido_en']) ?>)<?php if ($version['comentario_estudiante']): ?><br><small>Estudiante: <?= nl2br(e($version['comentario_estudiante'])) ?></small><?php endif; ?><?php if ($version['observacion_tutor']): ?><br><small>Revisión: <?= nl2br(e($version['observacion_tutor'])) ?></small><?php endif; ?>
