                    </li><?php endforeach; ?></ul><?php elseif ($milestone['tipo'] === 'informe' && (int) $milestone['requiere_informes'] === 1): ?><p>Sin informe cargado.</p><?php else: ?><p><?= e($milestone['observacion_estudiante'] ?? 'Sin entrega registrada.') ?></p><?php endif; ?>
