        <?php endif; ?>

        <section class="card mg-panel"><h2>Sesiones y asistencia</h2>
            <?php if ($detail['sesiones']): ?><?php foreach ($detail['sesiones'] as $session): ?><article class="mg-panel"><h3><?= e($session['titulo']) ?> · <?= e($session['tipo']) ?></h3><p><?= e($session['inicio']) ?><?= $session['fin'] ? ' – ' . e($session['fin']) : '' ?> · <?= e($session['modalidad']) ?> · <?= e($session['ubicacion'] ?? 'Sin ubicación') ?> · <?= e($session['estado']) ?><?= $session['tutor'] ? ' · Tutor: ' . e($session['tutor']) : '' ?></p><?php if ($session['descripcion']): ?><p><?= nl2br(e($session['descripcion'])) ?></p><?php endif; ?>
                    <?php if ($canManage || $role === 'tutor'): ?><form method="post" action="<?= e(app_url('modalidades-grado/seguimiento.php?id_trabajo=' . (int) $detail['id_trabajo'])) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id_trabajo" value="<?= (int) $detail['id_trabajo'] ?>"><input type="hidden" name="id_sesion" value="<?= (int) $session['id_sesion'] ?>"><table><thead><tr><th>Estudiante</th><th>Estado de asistencia</th><th>Observación</th></tr></thead><tbody><?php foreach ($session['asistentes'] as $attendee): ?><tr><td><?= e($attendee['estudiante']) ?> (<?= e($attendee['registro_universitario'] ?? '—') ?>)</td><td><select class="form-select" name="asistencia[<?= (int) $attendee['id_estudiante'] ?>]"><?php foreach (['pendiente'=>'Pendiente','presente'=>'Presente','ausente'=>'Ausente','justificada'=>'Justificada'] as $key=>$label): ?><option value="<?= e($key) ?>" <?= $attendee['estado']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></td><td><input class="form-control" name="observacion_asistencia[<?= (int) $attendee['id_estudiante'] ?>]" maxlength="500" value="<?= e($attendee['observacion'] ?? '') ?>"></td></tr><?php endforeach; ?></tbody></table><button class="btn btn-sm btn-primary" name="accion" value="guardar_asistencia">Guardar asistencia</button></form><?php else: ?><p>Asistencia registrada: <?= (int) $session['presentes'] ?> presente(s), <?= (int) $session['ausentes'] ?> ausente(s), <?= (int) $session['justificadas'] ?> justificada(s), <?= (int) $session['sin_registrar'] ?> pendiente(s).</p><?php endif; ?>
                </article><?php endforeach; ?><?php else: ?><p>No hay sesiones registradas.</p><?php endif; ?>
        </section>

        <section class="card mg-panel"><h2>MDG I y MDG II</h2><p>Los resultados son independientes del módulo general de Evaluaciones. Nota y porcentaje no aplican reglas automáticas de aprobación.</p>
            <?php foreach (['mdg1'=>'MDG I','mdg2'=>'MDG II'] as $stage=>$label): $result=$resultByStage[$stage]??null; ?><article class="mg-panel"><h3><?= e($label) ?> · <?= e($result['estado'] ?? 'pendiente') ?><?= $result && $result['nota']!==null ? ' · Nota ' . e($result['nota']) : '' ?></h3><?php if ($result && $result['observaciones']): ?><p><?= nl2br(e($result['observaciones'])) ?></p><?php endif; ?>
                <?php if ($result && $result['historial']): ?><details><summary>Historial de resultados</summary><ul><?php foreach ($result['historial'] as $event): ?><li><?= e($event['registrado_en']) ?> · <?= e(($event['estado_anterior']??'—').' → '.$event['estado_nuevo']) ?><?= $event['nota']===null?'':' · '.e($event['nota']) ?> · <?= e($event['registrado_por']) ?><?= $event['observaciones']?' — '.e($event['observaciones']):'' ?></li><?php endforeach; ?></ul></details><?php endif; ?>
                <?php if ($canManage || $role==='tutor'): ?><form class="mg-form-grid" method="post" action="<?= e(app_url('modalidades-grado/seguimiento.php?id_trabajo='.(int)$detail['id_trabajo'])) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id_trabajo" value="<?= (int)$detail['id_trabajo'] ?>"><input type="hidden" name="etapa" value="<?= e($stage) ?>"><label>Estado<select class="form-select" name="estado"><?php foreach (['pendiente','en_curso','observado','aprobado','reprobado'] as $state): ?><option value="<?= e($state) ?>" <?= ($result['estado']??'pendiente')===$state?'selected':'' ?>><?= e($state) ?></option><?php endforeach; ?></select></label><label>Nota<input class="form-control" type="number" min="0" max="100" step="0.01" name="nota" value="<?= e($result['nota']??'') ?>"></label><label>Observaciones<textarea class="form-control" name="observaciones" rows="2" maxlength="5000"></textarea></label><button class="btn btn-outline-primary" name="accion" value="guardar_etapa">Guardar <?= e($label) ?></button></form><?php endif; ?>
            </article><?php endforeach; ?>
        </section>
    <?php endif; ?>
</main>
